@@ -0,0 +1,37 @@
+// Sites (kitchens). Every location belongs to one site, and a batch belongs
+// to the site of its location. Items, suppliers, recipes and dishes are
+// shared by all sites. Domain functions that take a `site` only see that
+// site's batches; without one they see the whole store (tools, jobs).
+import { AppError } from "../errors.js";
+
+/** The site of requests that do not name one, and of data from before sites. */
+export const DEFAULT_SITE = "main";
+
+/** Every site, in file order. */
+export function listSites(store) {
+  return [...store.data.sites];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = store.data.sites.find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The site id a location belongs to (the default site when the location is not listed). */
+export function siteOfLocation(store, locationId) {
+  return store.data.locations.find((l) => l.id === locationId)?.site ?? DEFAULT_SITE;
+}
+
+/** True when the location is listed and belongs to `site` (any site when `site` is undefined). */
+export function hasLocation(store, locationId, site) {
+  return store.data.locations.some((l) => l.id === locationId && (site === undefined || l.site === site));
+}
+
+/** The batches of one site, or every batch when `site` is undefined. */
+export function siteBatches(store, site) {
+  if (site === undefined) return store.data.batches;
+  const bySite = new Map(store.data.locations.map((l) => [l.id, l.site]));
+  return store.data.batches.filter((b) => (bySite.get(b.location) ?? DEFAULT_SITE) === site);
+}
